{"code":"def transform(grid):
    g=[row[:] for row in grid]
    h=len(g); w=len(g[0])
    # identify non-6 colored cells and use their checkerboard parity
    pts=[(r,c) for r in range(h) for c in range(w) if g[r][c] not in (0,6)]
    if not pts: return g
    parity=(pts[0][0]+pts[0][1])%2
    # For each row, fill zero cells lying between the leftmost/rightmost 6 boundary
    for r in range(h):
        six=[c for c in range(w) if g[r][c]==6]
        if len(six)>=2:
            lo,hi=min(six),max(six)
            for c in range(lo+1,hi):
                if g[r][c]==0 and (r+c)%2==parity:
                    g[r][c]=pts and 2 if False else 3
    return g"}

